//! 🧪️ Actual immutable child roots and registry leases are looked up under exact bounded Native quotes.
use super::*;
use crate::child_view::{ChildContentEntry,MemberKey,ChildContentReadRetirement};
use semio_framework_value::retained_clone::RetainedCloneSource;
use store::os_store::snapshot_read::{ErasedSnapshotRead,SnapshotReadRegistryHandle};
use std::sync::Arc;
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn operation()->AppOperationContext{AppOperationContext{app_instance_id:4,parent_document_id:"original-layout".into(),operation_id:71,generation:3,canonical_base_revision:[31;32],retained:generous(),authoring_seed:"original-fixture".into()}}
fn observed<T>(g:RetainedCloneGrant,operation:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result}
fn deny(d:RetirementDemand,mut operation:impl FnMut(RetainedCloneGrant)->RetainedCloneProgress){for axis in 0..3{let mut g=exact(d);match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes-=1,_=>g.maximum_depth-=1}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||operation(g));assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}
fn insert(view:ChildContentView,key:MemberKey,index:usize,registry:&SnapshotReadRegistryHandle,payload:&Arc<String>)->ChildContentView{let lease=registry.try_issue(Arc::clone(payload)).unwrap_or_else(|_|panic!("actual immutable member registry"));view.insert_entry_admitted(index,ChildContentEntry{owner:key.owner,slot:key.slot,child_id:key.child_id,artifact_id:"original-artifact".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.fixture.child".into(),standard:"1".into(),subset:"*".into()},revision:[42;32],snapshot:ErasedSnapshotRead::new(Arc::clone(payload),lease)})}
fn run(row:&serde_json::Value,cut:Option<usize>){let key=MemberKey{owner:row["owner"].as_str().unwrap_or("").into(),slot:"backgroundDrawing".into(),child_id:if row["oversize"].as_bool()==Some(true){"x".repeat(257)}else if row["unicode"].as_bool()==Some(true){"drawing Grüße 🌍".into()}else{"drawing-document".into()}};let foreign_key=key.clone();let registry=SnapshotReadRegistryHandle::new();let payload=Arc::new(String::from("same actual original child payload"));let start=if key.child_id.len()<=CHILD_CONTENT_ID_BYTES{ChildContentView::hash(key.borrowed()).unwrap()}else{0};let count=row["collisions"].as_u64().unwrap_or(0)as usize;let mut view=ChildContentView::EMPTY;let mut collisions=0;for candidate in 0..{if collisions==count{break}let candidate=MemberKey{child_id:format!("collider-{candidate}"),..key.clone()};if ChildContentView::hash(candidate.borrowed()).unwrap()==start{view=insert(view,candidate,(start+collisions)%CHILD_CONTENT_SLOTS,&registry,&payload);collisions+=1}}if row["missing"].as_bool()!=Some(true){view=insert(view,key.clone(),(start+count)%CHILD_CONTENT_SLOTS,&registry,&payload)}let empty=ChildContentView::EMPTY;
 let(mut parent,_)=RetainedCloneSource::admit_owned(String::from("same actual original parent"),(),generous()).unwrap_or_else(|_|panic!("original retained parent"));let(mut other_parent,_)=RetainedCloneSource::admit_owned(String::from("same actual original parent"),(),generous()).unwrap_or_else(|_|panic!("other retained parent"));let mut operation=operation();let render=crate::AppRenderOperationContext{app_instance_id:operation.app_instance_id,base_revision:semio_framework_job::RevisionId(9),generation:semio_framework_job::Generation(operation.generation),canonical_base_revision:operation.canonical_base_revision,mounted_policy:semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1{preparation:generous(),maintenance:generous(),close:generous()}};let mut cursor=observed(exact(OriginalChildMemberLookup::birth_demand()),||OriginalChildMemberLookup::admit(exact(OriginalChildMemberLookup::birth_demand())).unwrap());let mut accepted=false;let mut failed=false;
 for turn in 0..cut.unwrap_or(10000){let substitution=if turn==0{""}else{row["substitute"].as_str().unwrap_or("")};let source=if substitution=="parent"{other_parent.borrow()}else if substitution=="projection"{parent.borrow().project(1,|value|value)}else{parent.borrow()};let catalog=if substitution=="root"{&empty}else{&view};let selected_key=if substitution=="key"{foreign_key.borrowed()}else{key.borrowed()};if substitution=="operation"{operation.operation_id=72}if substitution=="operationRevision"{operation.canonical_base_revision=[99;32]}let source_operation=if row["render"].as_bool()==Some(true)||substitution=="facet"{OriginalChildMemberOperation::Render{operation:&render,parent_document_id:&operation.parent_document_id}}else{OriginalChildMemberOperation::Command(&operation)};let d=match cursor.next_operation_demand::<String,_>(source,catalog,selected_key,source_operation){Ok(d)=>d,Err(_)=>{failed=true;break}};deny(d,|g|cursor.advance_operation::<String,_>(source,catalog,selected_key,source_operation,g).unwrap().progress);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance_operation::<String,_>(source,catalog,selected_key,source_operation,exact(d)));match result{Ok(step)=>{assert!(step.progress.fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));if let Some(read)=step.read{assert_eq!(&*read.read as*const String,Arc::as_ptr(&payload));let metadata=read.member_metadata();assert_eq!(metadata.parent_identity,parent.borrow().reference_identity().2);assert_eq!(metadata.child_id,key.child_id);assert_eq!(metadata.parent_revision,&operation.canonical_base_revision);accepted=true;break}},Err(error)=>{assert!(error.retained_progress().fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));failed=true;break}}}if cut.is_none(){assert_eq!(accepted,row["accept"].as_bool().unwrap(),"{}",row["name"]);assert_eq!(failed,!accepted)}cursor.begin_close();let d=cursor.close_demand();deny(d,|g|cursor.close_step(g).unwrap());observed(exact(d),||{let p=cursor.close_step(exact(d)).unwrap();((),p)});assert!(cursor.terminal_is_empty());
 let mut close=ChildContentReadRetirement::new(view);for _ in 0..100000{if close.terminal_is_empty(){break}let d=close.demands(generous().maximum_copy_bytes).unwrap();close.step(exact(d)).unwrap();}assert!(close.terminal_is_empty());assert!(registry.terminal_is_empty());drop(payload);let mut registry_close=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));while registry_close.is_some(){store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut registry_close,generous()).unwrap();}for source in [&mut parent,&mut other_parent]{while !source.terminal_is_empty(){let d=source.next_close_demand(generous().maximum_copy_bytes).unwrap();source.close_step(exact(d)).unwrap();}}}
#[test]fn actual_registry_member_lookup_matches_neutral_original_source_laws(){let laws:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),17);for row in laws["cases"].as_array().unwrap(){run(row,None)}for cut in [0,1,2,3,10,32,64,100]{run(&laws["cases"][0],Some(cut))}}

#[test]fn actual_render_view_lends_its_original_context_to_member_lookup(){
 use std::future::Future;
 let registry=SnapshotReadRegistryHandle::new();let payload=Arc::new(String::from("actual render member"));let key=MemberKey{owner:String::new(),slot:"backgroundDrawing".into(),child_id:"drawing-render".into()};let index=ChildContentView::hash(key.borrowed()).unwrap();let children=insert(ChildContentView::EMPTY,key.clone(),index,&registry,&payload);let(mut parent,_)=RetainedCloneSource::admit_owned(String::from("actual render parent"),(),generous()).unwrap_or_else(|_|panic!("original parent"));let operation=operation();let history=crate::HistoryView::empty();let render=crate::AppRenderOperationContext{app_instance_id:operation.app_instance_id,base_revision:semio_framework_job::RevisionId(9),generation:semio_framework_job::Generation(operation.generation),canonical_base_revision:operation.canonical_base_revision,mounted_policy:semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1{preparation:generous(),maintenance:generous(),close:generous()}};
 let children={let reference=parent.borrow();let future=crate::ArtifactView::with_render_context(reference.get(),&history,children,render,&operation.parent_document_id,None);let mut future=std::pin::pin!(future);let mut context=std::task::Context::from_waker(std::task::Waker::noop());let view=match future.as_mut().poll(&mut context){std::task::Poll::Ready(view)=>view,std::task::Poll::Pending=>panic!("render view constructor only transfers original fields")};let original=OriginalChildMemberOperation::from_view(&view).unwrap();match original{OriginalChildMemberOperation::Render{operation:actual,parent_document_id}=>{assert!(std::ptr::eq(actual,view.render_operation_ref().unwrap()));assert_eq!(parent_document_id.as_ptr(),operation.parent_document_id.as_ptr())},_=>panic!("render view must lend its actual render context")};let(mut lookup,_)=OriginalChildMemberLookup::admit(exact(OriginalChildMemberLookup::birth_demand())).unwrap();let mut accepted=false;for _ in 0..10000{let d=lookup.next_operation_demand::<String,_>(reference,&view.children,key.borrowed(),original).unwrap();let advance=observed(exact(d),||{let step=lookup.advance_operation::<String,_>(reference,&view.children,key.borrowed(),original,exact(d)).unwrap();let progress=step.progress;(step,progress)});if let Some(read)=advance.read{assert!(std::ptr::eq(&*read.read,Arc::as_ptr(&payload)));accepted=true;break}}assert!(accepted);lookup.begin_close();let d=lookup.close_demand();observed(exact(d),||{let progress=lookup.close_step(exact(d)).unwrap();((),progress)});assert!(lookup.terminal_is_empty());view.children};
 let mut close=ChildContentReadRetirement::new(children);for _ in 0..100000{if close.terminal_is_empty(){break}let d=close.demands(generous().maximum_copy_bytes).unwrap();close.step(exact(d)).unwrap();}assert!(close.terminal_is_empty());assert!(registry.terminal_is_empty());drop(payload);let mut alias=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));while alias.is_some(){store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut alias,generous()).unwrap();}while !parent.terminal_is_empty(){let d=parent.next_close_demand(generous().maximum_copy_bytes).unwrap();parent.close_step(exact(d)).unwrap();}
}
